DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia de la Diabetes$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia de la Diabetes$t$;
    RETURN;
  END IF;

  -- 01. Obesidad y diabetes tipo 2: tratamiento farmacológico del peso y uso responsable
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La meta que no era solo bajar de peso","texto":"Una paciente con diabetes tipo 2 y obesidad pregunta por un medicamento “para adelgazar” que vio en redes sociales. No tiene receta, no sabe si tiene registro sanitario y no ha modificado su alimentación. La obesidad es una enfermedad crónica que requiere evaluación y tratamiento, no un producto milagroso. El uso responsable incluye indicación, seguimiento y educación."},"objetivos":["Reconocer la obesidad como enfermedad crónica y factor de riesgo metabólico.","Diferenciar los fármacos con indicación en obesidad y diabetes.","Aplicar criterios de inicio, titulación y seguimiento.","Prevenir el uso irresponsable y los productos fraudulentos."],"conceptos":[{"icono":"Scale","termino":"Obesidad","definicion":"Enfermedad crónica multifactorial con exceso de grasa y riesgo metabólico, cardiovascular y mecánico."},{"icono":"Activity","termino":"GLP-1","definicion":"Fármacos que reducen el apetito y el peso, además de mejorar la glucosa en diabetes tipo 2."},{"icono":"Target","termino":"Meta de peso","definicion":"Pérdida gradual y sostenible, con mejora de comorbilidades, no solo una cifra estética."},{"icono":"ShieldCheck","termino":"Uso responsable","definicion":"Indicación clínica, receta, registro sanitario, seguimiento y educación."}],"secciones":[{"titulo":"La obesidad no es falta de voluntad","parrafos":["La obesidad es una enfermedad crónica con múltiples causas: genética, ambiente, sueño, estrés, medicamentos y acceso a alimentos. El tratamiento no se limita a “comer menos y moverse más”. La evaluación incluye comorbilidades, hábitos, salud mental y barreras. La meta es mejorar la salud y la calidad de vida, no solo el peso.","En diabetes tipo 2, la obesidad contribuye a la resistencia a la insulina y al riesgo cardiovascular. La pérdida de peso moderada, del 5 al 10 %, puede mejorar la glucosa, la presión y los lípidos. La sostenibilidad importa más que la velocidad."]},{"titulo":"Fármacos con indicación","parrafos":["Los agonistas GLP-1 y tirzepatida reducen el apetito y el peso, además de mejorar la glucosa. La semaglutida y la liraglutida tienen indicaciones en obesidad y diabetes; la tirzepatida también. El orlistat reduce la absorción de grasa y puede ser útil en algunos pacientes, pero tiene efectos digestivos y no es para todos.","No todos los fármacos para diabetes sirven para obesidad. La insulina y las sulfonilureas pueden aumentar el peso. La metformina es neutra. La elección depende del perfil, la comorbilidad, el costo y la preferencia. La farmacoterapia se acompaña de alimentación, actividad y sueño."]},{"titulo":"Uso responsable y prevención","parrafos":["El uso de fármacos para obesidad exige indicación, receta y seguimiento. Los productos comprados por internet, sin registro sanitario o con promesas milagrosas son un riesgo. El INVIMA ha alertado sobre productos falsificados y sustancias no declaradas. El QF debe verificar el registro y la cadena de suministro.","La educación incluye expectativas realistas, efectos adversos, titulación, costo y duración. La obesidad requiere tratamiento a largo plazo; suspender sin plan puede llevar a regain. La adherencia y el seguimiento son parte del éxito."]}],"errores":[{"error":"Prometer pérdida de peso rápida.","correccion":"La pérdida debe ser gradual y sostenible."},{"error":"Usar fármacos sin indicación ni receta.","correccion":"Se requiere evaluación clínica y seguimiento."},{"error":"No revisar el registro sanitario.","correccion":"Los productos fraudulentos son un riesgo real."}],"comprueba":[{"pregunta":"¿Qué porcentaje de pérdida de peso mejora la salud?","respuesta":"Un 5 a 10 % puede mejorar glucosa, presión y lípidos."},{"pregunta":"¿Qué fármacos reducen peso y glucosa?","respuesta":"GLP-1 y tirzepatida, según indicación."},{"pregunta":"¿Qué verificar antes de recomendar un producto?","respuesta":"Registro sanitario, indicación, composición y cadena de suministro."}],"resumen":["La obesidad es una **enfermedad crónica**.","La meta es **salud y sostenibilidad**, no solo peso.","GLP-1 y tirzepatida tienen indicaciones específicas.","El **registro sanitario** y el seguimiento son obligatorios."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"INVIMA. Alertas sanitarias.","url":"https://www.invima.gov.co/alertas-sanitarias"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Balanza, plato saludable y un frasco sin registro tachado con una X.","alt":"Obesidad, diabetes y uso responsable de medicamentos"}],"keywords":["obesidad y diabetes tipo 2","fármacos para obesidad","glp-1 obesidad","tirzepatida obesidad","pérdida de peso saludable","productos milagroso riesgo","curso farmacoterapia diabetes"],"mapa":{"centro":"Obesidad y diabetes","ramas":[{"titulo":"Evaluación","icono":"ClipboardList","nodos":["IMC","Comorbilidades","Alimentación"]},{"titulo":"Fármacos","icono":"Pill","nodos":["GLP-1","Tirzepatida","Orlistat"]},{"titulo":"Metas","icono":"Target","nodos":["5-10 %","Sostenible","Calidad de vida"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Productos falsos","Automedicación","Efectos adversos"]}]},"proceso":{"titulo":"Abordaje farmacológico del peso","intro":"","pasos":[{"titulo":"Evaluar","detalle":"IMC, comorbilidades, hábitos y medicamentos que aumentan peso.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Definir meta","detalle":"Pérdida gradual y mejora de salud, no solo estética.","icono":"Target","evidencia":"Meta."},{"titulo":"Elegir fármaco","detalle":"Según diabetes, riesgo cardiovascular, costo y preferencia.","icono":"Pill","evidencia":"Selección."},{"titulo":"Titular","detalle":"Inicio bajo y aumento gradual.","icono":"RefreshCw","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"Peso, tolerancia, adherencia y comorbilidades.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"El producto milagroso","contexto":"Paciente con obesidad y diabetes tipo 2 trae un frasco sin registro sanitario que promete “perder 10 kg en un mes”. Quiere suspender la metformina y usar solo ese producto.","pregunta":"¿Qué debe hacer el QF?","opciones":[{"texto":"Recomendarlo porque es natural.","correcta":false,"retro":"Lo natural no significa seguro. Sin registro ni composición verificable, el riesgo es alto."},{"texto":"Desaconsejarlo, explicar los riesgos, verificar el registro y proponer un plan con evaluación médica.","correcta":true,"retro":"El uso responsable exige producto registrado, indicación y seguimiento. La metformina no se suspende sin evaluación."},{"texto":"Duplicar la metformina para compensar.","correcta":false,"retro":"No se compensa un producto no verificado con más medicamento."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Obesidad y diabetes tipo 2: tratamiento farmacológico del peso y uso responsable$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Obesidad y diabetes tipo 2: tratamiento farmacológico del peso y uso responsable$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Seguimiento farmacoterapéutico de la persona con diabetes en el servicio farmacéutico colombiano
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La consulta que nadie cobraba","texto":"Una farmacia de barrio decide abrir un espacio semanal para revisar la medicación de personas con diabetes. En tres meses detecta hipoglucemias, errores de técnica, interacciones y pacientes que no pueden pagar el tratamiento. El seguimiento farmacoterapéutico no es un lujo: es una intervención que mejora resultados y reduce costos."},"objetivos":["Diseñar un proceso de seguimiento farmacoterapéutico en diabetes.","Identificar problemas relacionados con los medicamentos.","Documentar y comunicar intervenciones al equipo tratante.","Medir resultados y asegurar la continuidad."],"conceptos":[{"icono":"Users","termino":"Seguimiento","definicion":"Proceso continuo de evaluación, intervención y monitoreo de la farmacoterapia."},{"icono":"ClipboardList","termino":"PRM","definicion":"Problema relacionado con el medicamento: necesidad, efectividad, seguridad o adherencia."},{"icono":"FileCheck","termino":"Documentación","definicion":"Registro de la evaluación, la intervención y el resultado para asegurar trazabilidad."},{"icono":"LineChart","termino":"Resultado","definicion":"Cambio clínico o humanístico medido después de la intervención."}],"secciones":[{"titulo":"El proceso","parrafos":["El seguimiento farmacoterapéutico incluye entrevista, revisión de la medicación, identificación de problemas, intervención, documentación y monitoreo. En diabetes, se revisan la indicación, la efectividad, la seguridad y la adherencia. También se exploran barreras de acceso, creencias y calidad de vida.","La entrevista debe ser estructurada y respetuosa. Se pregunta por síntomas, horarios, técnica, hipoglucemias, costo y apoyo familiar. La información se registra en una ficha que permita seguir la evolución."]},{"titulo":"Intervenciones frecuentes","parrafos":["Las intervenciones incluyen educación sobre técnica de inyección, ajuste de horarios, revisión de interacciones, derivación por hipoglucemia, simplificación del esquema y apoyo para acceder a medicamentos. La intervención se comunica al médico con datos concretos y una propuesta.","No todas las intervenciones requieren cambio de medicamento. A veces basta con explicar, corregir la técnica o resolver una barrera económica. El QF debe reconocer sus límites y derivar cuando sea necesario."]},{"titulo":"Documentación y resultados","parrafos":["La documentación incluye el problema identificado, la intervención, la respuesta y la fecha de seguimiento. Se usan indicadores como HbA1c, eventos de hipoglucemia, adherencia, presión, peso y calidad de vida. La medición permite demostrar el valor del servicio.","La continuidad es clave. El paciente debe saber cuándo volver y cómo contactar. La coordinación con el equipo tratante y con otros servicios de salud evita duplicidades y mejora la atención."]}],"errores":[{"error":"Hacer seguimiento solo con la HbA1c.","correccion":"Se revisan síntomas, adherencia, seguridad y calidad de vida."},{"error":"No documentar la intervención.","correccion":"Sin registro no hay trazabilidad ni evaluación."},{"error":"No explorar barreras de acceso.","correccion":"El costo y la cobertura explican muchos incumplimientos."}],"comprueba":[{"pregunta":"¿Qué evalúa el seguimiento farmacoterapéutico?","respuesta":"Indicación, efectividad, seguridad y adherencia."},{"pregunta":"¿Qué es un PRM?","respuesta":"Un problema relacionado con el medicamento."},{"pregunta":"¿Cómo se demuestra el valor del servicio?","respuesta":"Con documentación y medición de resultados."}],"resumen":["El seguimiento es un **proceso continuo**.","Incluye evaluación, intervención, documentación y medición.","Las **barreras de acceso** son parte del problema.","La documentación demuestra el valor del servicio."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"Cipolle RJ, Strand LM, Morley PC. Pharmaceutical care practice: the patient-centered approach to medication management services. 3.ª ed. Nueva York: McGraw-Hill Medical; 2012.","url":"https://www.mhprofessional.com/pharmaceutical-care-practice-9780071759029-usa"}],"imagenes":[{"ubicacion":"Sección del proceso","descripcion":"Ciclo de cinco pasos con ficha farmacéutica, entrevista y gráfico de resultados.","alt":"Seguimiento farmacoterapéutico en diabetes"}],"keywords":["seguimiento farmacoterapéutico diabetes","atención farmacéutica diabetes","problemas relacionados con medicamentos","adherencia diabetes","servicio farmacéutico colombia","curso farmacoterapia diabetes"],"mapa":{"centro":"Seguimiento farmacoterapéutico","ramas":[{"titulo":"Evaluar","icono":"Search","nodos":["Indicación","Efectividad","Seguridad","Adherencia"]},{"titulo":"Intervenir","icono":"Lightbulb","nodos":["Educar","Ajustar","Derivar"]},{"titulo":"Documentar","icono":"FileCheck","nodos":["Ficha","Nota","Comunicación"]},{"titulo":"Medir","icono":"LineChart","nodos":["HbA1c","Hipoglucemias","Calidad de vida"]}]},"proceso":{"titulo":"Ciclo de seguimiento en cinco pasos","intro":"","pasos":[{"titulo":"Entrevistar","detalle":"Historia, medicamentos, hábitos y barreras.","icono":"Users","evidencia":"Ficha."},{"titulo":"Evaluar","detalle":"Indicación, efectividad, seguridad y adherencia.","icono":"Search","evidencia":"PRM."},{"titulo":"Intervenir","detalle":"Educar, ajustar o derivar.","icono":"Lightbulb","evidencia":"Nota."},{"titulo":"Documentar","detalle":"Registrar la intervención y la respuesta.","icono":"FileCheck","evidencia":"Registro."},{"titulo":"Medir","detalle":"Revisar resultados y programar seguimiento.","icono":"LineChart","evidencia":"Indicador."}]},"caso":{"titulo":"La paciente que no vuelve","contexto":"Paciente con diabetes tipo 2 que no asiste a los controles. En la farmacia se detecta que no puede pagar el medicamento y usa una dosis menor.","pregunta":"¿Cuál es la intervención más adecuada?","opciones":[{"texto":"Regañarla por no cumplir.","correcta":false,"retro":"El regaño no resuelve la barrera y deteriora la relación."},{"texto":"Explorar la barrera, buscar una alternativa cubierta y coordinar con el equipo.","correcta":true,"retro":"La adherencia mejora cuando se resuelven las causas, no cuando se culpa al paciente."},{"texto":"Suspender el seguimiento.","correcta":false,"retro":"La falta de asistencia es una señal para intervenir, no para abandonar."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Seguimiento farmacoterapéutico de la persona con diabetes en el servicio farmacéutico colombiano$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
