  END IF;

  -- 03. Farmacovigilancia de antidiabéticos: alertas recientes, productos falsificados y reporte al INVIMA
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La pluma que no era Ozempic","texto":"Un paciente compra una pluma de semaglutida en un sitio no autorizado. La etiqueta parece correcta, pero el lote no coincide y el producto no tiene registro verificable. El INVIMA ha alertado sobre falsificaciones. La farmacovigilancia no es solo reportar reacciones adversas: también es detectar productos falsificados y proteger al paciente."},"objetivos":["Reconocer las alertas de seguridad de antidiabéticos.","Identificar productos falsificados y canales no autorizados.","Aplicar el reporte de sospechas de reacciones adversas al INVIMA.","Educar al paciente sobre el uso seguro y la verificación del registro."],"conceptos":[{"icono":"ShieldCheck","termino":"Farmacovigilancia","definicion":"Actividades para detectar, evaluar, prevenir y comunicar reacciones adversas y problemas de seguridad."},{"icono":"AlertTriangle","termino":"Alerta sanitaria","definicion":"Comunicación oficial sobre un riesgo de un medicamento o producto; puede incluir retiro o restricción."},{"icono":"Search","termino":"Producto falsificado","definicion":"Producto que imita la apariencia de uno legítimo sin serlo; puede contener sustancias peligrosas o no tener principio activo."},{"icono":"FileCheck","termino":"Reporte","definicion":"Notificación de una sospecha de reacción adversa o problema de calidad a la autoridad sanitaria."}],"secciones":[{"titulo":"Alertas que el QF debe conocer","parrafos":["El INVIMA ha emitido alertas sobre semaglutida, tirzepatida y otros antidiabéticos, incluidas falsificaciones, productos sin registro y problemas de calidad. Las alertas pueden cambiar la disponibilidad, la prescripción o la educación. El QF debe consultar las fuentes oficiales y no basarse en cadenas de WhatsApp.","Las alertas no siempre significan que el fármaco sea inseguro. Pueden referirse a un lote, un canal de venta o una población específica. La interpretación correcta evita alarmismo y permite tomar decisiones."]},{"titulo":"Productos falsificados","parrafos":["Los productos falsificados pueden tener el aspecto del original, pero no el principio activo, la dosis o la calidad. Se compran por internet, en redes sociales o en lugares no autorizados. El riesgo incluye falta de eficacia, hipoglucemia, contaminación y reacciones graves.","El QF debe verificar el registro sanitario, el lote, la fecha de vencimiento, el etiquetado y la cadena de frío. Si sospecha un producto falsificado, no lo dispensa, lo separa y reporta a la autoridad. También educa al paciente sobre los canales autorizados."]},{"titulo":"Reporte de reacciones adversas","parrafos":["Cualquier sospecha de reacción adversa debe reportarse al programa de farmacovigilancia de la institución o al INVIMA. El reporte incluye datos del paciente, el medicamento, la reacción, la evolución y la fuente. No se requiere certeza para reportar.","La farmacovigilancia también incluye problemas de calidad, falta de eficacia y errores de medicación. El QF puede educar al paciente para que consulte ante síntomas y no suspenda el tratamiento sin orientación."]}],"errores":[{"error":"Reportar solo cuando hay certeza.","correccion":"La sospecha es suficiente para notificar."},{"error":"Ignorar las alertas del INVIMA.","correccion":"Las alertas cambian la práctica y la educación."},{"error":"Comprar o recomendar por internet.","correccion":"Verificar el canal y el registro sanitario."}],"comprueba":[{"pregunta":"¿Qué es una alerta sanitaria?","respuesta":"Una comunicación oficial sobre un riesgo de un medicamento o producto."},{"pregunta":"¿Qué verificar en una pluma?","respuesta":"Registro, lote, etiqueta, vencimiento y cadena de frío."},{"pregunta":"¿Cuándo reportar una sospecha?","respuesta":"Siempre que se sospeche, sin esperar certeza."}],"resumen":["La farmacovigilancia incluye **alertas y productos falsificados**.","La verificación del **registro y el lote** es obligatoria.","La sospecha se reporta, no se guarda.","La educación protege al paciente."],"referencias":[{"cita":"INVIMA. Alertas sanitarias.","url":"https://www.invima.gov.co/alertas-sanitarias"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de productos falsificados","descripcion":"Caja y pluma con lote que no coincide, lupa y sello de alerta sanitaria.","alt":"Detección de productos falsificados de semaglutida"}],"keywords":["farmacovigilancia antidiabéticos","alertas invima semaglutida","productos falsificados ozempic","reporte reacciones adversas","tirzepatida falsificada","seguridad medicamentos diabetes"],"mapa":{"centro":"Farmacovigilancia","ramas":[{"titulo":"Alertas","icono":"AlertTriangle","nodos":["Semaglutida","Tirzepatida","Productos falsos"]},{"titulo":"Detección","icono":"Search","nodos":["Lote","Registro","Etiqueta"]},{"titulo":"Reporte","icono":"FileCheck","nodos":["INVIMA","Programa","Documentación"]},{"titulo":"Educación","icono":"Users","nodos":["Canales autorizados","Síntomas","Adherencia"]}]},"proceso":{"titulo":"Cómo actuar ante una sospecha","intro":"","pasos":[{"titulo":"Detectar","detalle":"Síntomas, falta de eficacia, lote o producto sospechoso.","icono":"Search","evidencia":"Registro."},{"titulo":"Verificar","detalle":"Registro, lote, etiqueta y canal de compra.","icono":"ShieldCheck","evidencia":"Verificación."},{"titulo":"Retirar","detalle":"Separar el producto y evitar su uso.","icono":"AlertTriangle","evidencia":"Producto separado."},{"titulo":"Reportar","detalle":"Notificar al programa o al INVIMA.","icono":"FileCheck","evidencia":"Reporte."},{"titulo":"Educar","detalle":"Explicar el riesgo y los canales seguros.","icono":"Users","evidencia":"Educación."}]},"caso":{"titulo":"Lote que no coincide","contexto":"Paciente trae una pluma de semaglutida con un lote que no coincide con la caja y sin factura. Quiere usarla porque le costó menos.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Usarla porque la pluma parece original.","correcta":false,"retro":"La apariencia no garantiza autenticidad. El lote y la cadena de suministro son clave."},{"texto":"No usarla, verificar el registro y reportar la sospecha.","correcta":true,"retro":"La seguridad del paciente es prioritaria. Se reporta y se orienta a un canal autorizado."},{"texto":"Cambiar la etiqueta y dispensarla.","correcta":false,"retro":"Manipular la etiqueta es peligroso e ilegal."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Farmacovigilancia de antidiabéticos: alertas recientes, productos falsificados y reporte al INVIMA$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Farmacovigilancia de antidiabéticos: alertas recientes, productos falsificados y reporte al INVIMA$t$;
