  -- 04. Caso integrador: DM2 con enfermedad cardiorrenal, obesidad, polifarmacia y uso de un producto fraudulento
  v_data := $j${"v":1,"duracion":30,"gancho":{"titulo":"Todo junto en una sola consulta","texto":"Don Rafael tiene 66 años, diabetes tipo 2, insuficiencia cardíaca, ERC, obesidad, hipertensión y artrosis. Toma nueve medicamentos, usa un producto “natural” sin registro y ha tenido una hipoglucemia. La consulta exige priorizar, revisar interacciones, ajustar dosis y educar. Es el caso que integra todo el curso."},"objetivos":["Integrar los conocimientos del curso en un caso complejo.","Priorizar problemas de seguridad y efectividad.","Revisar polifarmacia, interacciones y productos fraudulentos.","Diseñar un plan de seguimiento realista y centrado en la persona."],"conceptos":[{"icono":"Layers","termino":"Polifarmacia","definicion":"Uso de múltiples medicamentos con riesgo de interacciones y efectos adversos."},{"icono":"Activity","termino":"Cardiorrenal","definicion":"Interacción entre corazón y riñón; guía la elección de antidiabéticos."},{"icono":"AlertTriangle","termino":"Riesgo","definicion":"Hipoglucemia, deshidratación, progresión renal o evento cardiovascular."},{"icono":"Users","termino":"Plan","definicion":"Conjunto de intervenciones acordadas, documentadas y con seguimiento."}],"secciones":[{"titulo":"Priorizar","parrafos":["El primer paso es identificar el riesgo más urgente: hipoglucemia, deshidratación, interacción o producto fraudulento. Luego se revisan las indicaciones y la efectividad de cada medicamento. No se añade nada nuevo hasta entender lo que ya toma.","La revisión incluye dosis, función renal, presión, glucometrías, síntomas y barreras. El producto sin registro se separa y se reporta. La educación se adapta al paciente y al cuidador."]},{"titulo":"Ajustar","parrafos":["Se ajustan los antidiabéticos según la TFG y el riesgo de hipoglucemia. Se revisan diuréticos y presión al iniciar o mantener un iSGLT2. Se elige un GLP-1 si hay riesgo cardiovascular o obesidad, con titulación y seguimiento. La insulina se ajusta con glucometrías.","La polifarmacia se simplifica cuando es posible. Se eliminan duplicidades y medicamentos sin indicación. Se revisan interacciones con anticoagulantes, antiinflamatorios y productos naturales."]},{"titulo":"Seguir","parrafos":["El plan incluye fechas de control, metas y señales de alarma. Se revisan HbA1c, TFG, albuminuria, presión, peso y eventos de hipoglucemia. La adherencia y la calidad de vida son resultados importantes.","El QF documenta la intervención y la comunica al equipo. Si el paciente no puede acceder a un fármaco, se busca una alternativa. La continuidad y la confianza sostienen el plan."]}],"errores":[{"error":"Añadir fármacos sin revisar los existentes.","correccion":"La polifarmacia exige revisión completa."},{"error":"Ignorar el producto fraudulento.","correccion":"Se separa, se reporta y se educa."},{"error":"No priorizar la hipoglucemia.","correccion":"Es el riesgo inmediato más grave."}],"comprueba":[{"pregunta":"¿Qué se prioriza en un caso complejo?","respuesta":"El riesgo más urgente: hipoglucemia, interacciones o deshidratación."},{"pregunta":"¿Qué hacer con un producto sin registro?","respuesta":"No usarlo, separarlo y reportarlo."},{"pregunta":"¿Qué resultados se miden?","respuesta":"HbA1c, TFG, albuminuria, presión, peso, hipoglucemias y calidad de vida."}],"resumen":["La seguridad se prioriza sobre la optimización.","La **polifarmacia** exige revisión completa.","El producto fraudulento se reporta.","El plan debe ser realista y con seguimiento."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"INVIMA. Alertas sanitarias.","url":"https://www.invima.gov.co/alertas-sanitarias"}],"imagenes":[{"ubicacion":"Sección del caso","descripcion":"Paciente mayor con nueve medicamentos, un producto sin registro y un plan de prioridades.","alt":"Caso integrador de diabetes con comorbilidades y polifarmacia"}],"keywords":["caso integrador diabetes","diabetes cardiorrenal obesidad","polifarmacia diabetes","producto fraudulento diabetes","hipoglucemia erc","seguimiento farmacoterapéutico"],"mapa":{"centro":"Caso integrador","ramas":[{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Hipoglucemia","Volumen","Interacciones"]},{"titulo":"Corazón","icono":"Activity","nodos":["iSGLT2","Diurético","Presión"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG","Albuminuria","Ajuste"]},{"titulo":"Persona","icono":"Users","nodos":["Producto falso","Adherencia","Costo"]}]},"proceso":{"titulo":"Abordaje integrador en cinco pasos","intro":"","pasos":[{"titulo":"Revisar todo","detalle":"Medicamentos, productos naturales, síntomas y barreras.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Priorizar","detalle":"Identificar el riesgo más urgente.","icono":"AlertTriangle","evidencia":"Prioridad."},{"titulo":"Ajustar","detalle":"Dosis, interacciones y elección cardiorrenal.","icono":"Pill","evidencia":"Plan."},{"titulo":"Educar","detalle":"Hipoglucemia, volumen, producto falso y adherencia.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"Metas, eventos y calidad de vida.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"El producto natural y la hipoglucemia","contexto":"Rafael, 66 años, DM2, insuficiencia cardíaca, ERC, obesidad, nueve medicamentos y un producto sin registro. Hipoglucemia reciente y TFG 34 ml/min.","pregunta":"¿Cuál es la primera prioridad?","opciones":[{"texto":"Añadir otro antidiabético.","correcta":false,"retro":"Antes de añadir, hay que revisar la hipoglucemia, la TFG y el producto fraudulento."},{"texto":"Revisar el esquema que causa hipoglucemia, suspender el producto no registrado y ajustar por TFG.","correcta":true,"retro":"La seguridad es primero. Luego se optimiza el resto del esquema."},{"texto":"Mantener todo y controlar en seis meses.","correcta":false,"retro":"La hipoglucemia y la TFG baja requieren intervención oportuna."}]}}$j$::jsonb;
