  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha que resume lo esencial","texto":"En la farmacia, el QF necesita responder rápido: dosis, ajuste renal, efectos adversos y qué preguntar al paciente. Esta ficha resume la metformina para consulta rápida, sin reemplazar la ficha técnica ni el criterio clínico."},"objetivos":["Recordar la dosis y el ajuste renal de la metformina.","Reconocer los efectos adversos y las contraindicaciones.","Aplicar la educación clave al paciente.","Identificar interacciones y signos de alarma."],"conceptos":[{"icono":"Pill","termino":"Metformina","definicion":"Biguanida que reduce la gluconeogénesis y mejora la sensibilidad a la insulina."},{"icono":"Droplets","termino":"TFG","definicion":"Guía el ajuste: no iniciar <45, reducir 30-44, contraindicar <30."},{"icono":"AlertTriangle","termino":"Acidosis láctica","definicion":"Rara pero grave; riesgo en hipoxia, sepsis, deshidratación o insuficiencia renal."},{"icono":"Droplets","termino":"B12","definicion":"Puede disminuir con uso prolongado; vigilar anemia y neuropatía."}],"secciones":[{"titulo":"Dosis y ajuste","parrafos":["Iniciar 500 mg una o dos veces al día con comida y titular cada una o dos semanas. La dosis habitual es 1.000 a 2.000 mg al día. Con TFG 45-59 revisar; con 30-44 no iniciar y reducir si ya está en uso; con <30 contraindicada.","Suspender antes de contraste yodado o cirugía mayor; reiniciar cuando la función renal sea estable. En enfermedad aguda con vómito, diarrea o mala ingesta, aplicar reglas de días de enfermedad."]},{"titulo":"Seguridad","parrafos":["Los efectos digestivos son frecuentes al inicio y mejoran con titulación. La B12 puede disminuir con uso prolongado. La acidosis láctica es rara pero grave. Se debe preguntar por alcohol, función renal y síntomas de hipoxia o deshidratación.","No causa hipoglucemia por sí sola. Si se combina con insulina o sulfonilurea, el riesgo depende del otro fármaco."]},{"titulo":"Educación","parrafos":["Explicar la toma con comida, la titulación y los síntomas digestivos. Advertir sobre el alcohol, el contraste y la cirugía. Revisar la función renal al menos una vez al año y la B12 en pacientes de riesgo.","La metformina no es nefrotóxica, pero requiere ajuste por función renal. El paciente debe saber por qué se suspende temporalmente en algunos procedimientos."]}],"errores":[{"error":"Suspender por creatinina aislada.","correccion":"Calcular TFG."},{"error":"No advertir sobre contraste.","correccion":"Suspender temporalmente."},{"error":"No revisar B12.","correccion":"Vigilar en uso prolongado."}],"comprueba":[{"pregunta":"¿Cuándo se contraindica?","respuesta":"TFG <30 ml/min."},{"pregunta":"¿Cómo se inicia?","respuesta":"500 mg con comida y titulación gradual."},{"pregunta":"¿Qué se suspende antes de contraste?","respuesta":"La metformina, temporalmente."}],"resumen":["Metformina: **TFG** manda.","Inicio bajo y con comida.","Vigilar B12 y acidosis láctica.","Suspender antes de contraste o cirugía."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta resumen con dosis, TFG, efectos adversos y educación.","alt":"Ficha rápida de metformina"}],"keywords":["metformina ficha","metformina dosis","metformina tfg","metformina efectos adversos","metformina b12"],"mapa":{"centro":"Metformina","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["500 mg con comida","Titular","1-2 g/día"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG <45","TFG <30","Suspender"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Digestivo","B12","Láctico"]},{"titulo":"Educación","icono":"Users","nodos":["Con comida","No alcohol","Contraste"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"Diabetes tipo 2, prediabetes seleccionada o SOP.","icono":"Target","evidencia":"Fórmula."},{"titulo":"TFG","detalle":"Revisar y ajustar.","icono":"Droplets","evidencia":"Resultado."},{"titulo":"Dosis","detalle":"Inicio bajo y titulación.","icono":"Pill","evidencia":"Esquema."},{"titulo":"Educación","detalle":"Comida, alcohol, contraste y efectos.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Tolerancia, B12 y función renal.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"TFG 42 y metformina","contexto":"Paciente con TFG 42 ml/min y metformina 1 g cada 12 horas. Sin síntomas.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Mantener la dosis alta.","correcta":false,"retro":"Con TFG 30-44 se recomienda no iniciar y reducir si ya está en uso."},{"texto":"Revisar con el médico la reducción de dosis y vigilar función renal.","correcta":true,"retro":"La TFG obliga a ajustar y seguir."},{"texto":"Suspender sin avisar.","correcta":false,"retro":"La suspensión debe coordinarse y acompañarse de alternativa."}]}}$j$::jsonb;
