  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de la semaglutida","texto":"Semaglutida subcutánea y oral tienen reglas distintas. Esta ficha resume dosis, titulación, seguridad y educación para la dispensación. La formulación oral exige ayunas y 30 minutos antes de comer; la subcutánea es semanal. Revisar la técnica, la conservación y los antecedentes de tiroides o pancreatitis antes de dispensar."},"objetivos":["Diferenciar las formulaciones y sus reglas.","Recordar la titulación y los efectos adversos.","Reconocer contraindicaciones y alertas.","Educar al paciente sobre técnica y adherencia."],"conceptos":[{"icono":"Activity","termino":"GLP-1","definicion":"Agonista que reduce glucosa y peso."},{"icono":"Syringe","termino":"Subcutánea","definicion":"Semanal, titulación gradual."},{"icono":"Pill","termino":"Oral","definicion":"Diaria, ayunas, 30 minutos."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Gastrointestinal, pancreatitis, tiroides, retinopatía."}],"secciones":[{"titulo":"Dosis","parrafos":["Subcutánea: iniciar 0,25 mg semanal y titular según objetivo y tolerancia. Oral: iniciar 3 mg al día y aumentar según ficha técnica. La oral se toma en ayunas con poca agua y se espera 30 minutos.","No son intercambiables mg a mg. La elección depende de preferencia, adherencia y cobertura.","Si se olvida una dosis semanal, se aplica lo antes posible dentro de los cinco días siguientes; si han pasado más días, se espera la siguiente dosis. En la formulación oral, si se olvida una toma, no se duplica al día siguiente. La conservación y la cadena de frío deben revisarse en cada dispensación."]},{"titulo":"Seguridad","parrafos":["Náuseas, vómito, diarrea y estreñimiento son frecuentes. Vigilar pancreatitis, colelitiasis, retinopatía y tiroides. Evitar en embarazo, lactancia y antecedente de carcinoma medular de tiroides o MEN2.","La deshidratación por vómito puede requerir suspensión temporal y evaluación.","La pancreatitis se sospecha ante dolor abdominal persistente que irradia a la espalda; se suspende y se evalúa. La colelitiasis puede manifestarse con dolor en el hipocondrio derecho. En pacientes con retinopatía preexistente se recomienda vigilancia oftalmológica durante la pérdida de peso."]},{"titulo":"Educación","parrafos":["Enseñar técnica de inyección, conservación y reglas de la formulación oral. Explicar que los efectos digestivos suelen mejorar con la titulación. Revisar la adherencia y el costo.","La semaglutida no es un tratamiento estético; se usa con indicación y seguimiento.","La pluma se conserva refrigerada antes del primer uso y luego según la ficha técnica. Se rota el sitio de inyección y se revisa la técnica. La adherencia al esquema semanal o diario debe evaluarse en cada contacto, junto con el costo y la cobertura."]}],"errores":[{"error":"Tomar la oral con alimentos.","correccion":"Ayunas y 30 minutos."},{"error":"Cambiar de formulación sin ajustar.","correccion":"No son intercambiables."},{"error":"No revisar tiroides.","correccion":"Preguntar por antecedentes."}],"comprueba":[{"pregunta":"¿Cómo se toma la oral?","respuesta":"En ayunas, con agua, 30 minutos antes de comer."},{"pregunta":"¿Frecuencia subcutánea?","respuesta":"Semanal."},{"pregunta":"¿Qué vigilar?","respuesta":"Gastrointestinal, pancreatitis, tiroides y retinopatía."}],"resumen":["Dos formulaciones, **reglas distintas**.","Titulación gradual.","Vigilar tiroides y pancreatitis.","Educación y adherencia."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Wegovy 0,25 mg FlexTouch solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1211608006/FT_1211608006.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con pluma semanal y tableta diaria, reloj de 30 minutos y lista de seguridad.","alt":"Ficha rápida de semaglutida"}],"keywords":["semaglutida ficha","semaglutida oral","semaglutida subcutánea","semaglutida dosis","semaglutida seguridad"],"mapa":{"centro":"Semaglutida","ramas":[{"titulo":"Subcutánea","icono":"Syringe","nodos":["Semanal","Titular","0,25 mg"]},{"titulo":"Oral","icono":"Pill","nodos":["Diaria","Ayunas","30 min"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Náuseas","Pancreatitis","Tiroides"]},{"titulo":"Educación","icono":"Users","nodos":["Técnica","Conservación","Adherencia"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Formulación","detalle":"Subcutánea u oral.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Dosis","detalle":"Inicio y titulación.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Tiroides, pancreatitis, embarazo.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"Técnica y reglas.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Tolerancia y adherencia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"La tableta con café","contexto":"Paciente toma semaglutida oral con café y desayuno. HbA1c no mejora.","pregunta":"¿Qué corregir?","opciones":[{"texto":"Aumentar la dosis.","correcta":false,"retro":"Primero corregir la administración."},{"texto":"Tomar en ayunas con agua y esperar 30 minutos.","correcta":true,"retro":"La comida y el café reducen la absorción."},{"texto":"Cambiar a insulina.","correcta":false,"retro":"No es el siguiente paso automático."}]}}$j$::jsonb;
