  -- 07. Ficha: Tirzepatida
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de tirzepatida","texto":"Tirzepatida es un agonista dual GIP/GLP-1 con titulación específica. Esta ficha resume lo esencial para dispensar y educar. Se inicia con 2,5 mg semanales y se aumenta cada cuatro semanas. Verificar el registro sanitario, el lote y la cadena de suministro antes de cualquier dispensación. La hidratación, la titulación lenta y la revisión de la insulina o sulfonilurea reducen el riesgo de efectos adversos. La ficha también recuerda que la pérdida de peso debe ser gradual y que el tratamiento no sustituye la alimentación ni la actividad física."},"objetivos":["Recordar la titulación y la dosis.","Reconocer efectos adversos y contraindicaciones.","Verificar el registro sanitario.","Educar sobre técnica y expectativas."],"conceptos":[{"icono":"Activity","termino":"GIP/GLP-1","definicion":"Agonista dual que reduce glucosa y peso."},{"icono":"Syringe","termino":"Titulación","definicion":"2,5 mg y aumentos cada 4 semanas."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Gastrointestinal, pancreatitis, tiroides, productos falsos."},{"icono":"ShieldCheck","termino":"Registro","definicion":"Verificar antes de dispensar."}],"secciones":[{"titulo":"Dosis","parrafos":["Iniciar 2,5 mg semanal durante cuatro semanas y aumentar a 5 mg; luego 7,5, 10, 12,5 o 15 mg con incrementos de al menos cuatro semanas. La titulación lenta reduce los síntomas digestivos.","Revisar la técnica de inyección y la conservación. No duplicar dosis olvidadas."]},{"titulo":"Seguridad","parrafos":["Náuseas, diarrea, vómito y estreñimiento son frecuentes. Vigilar pancreatitis, colelitiasis, tiroides e hipoglucemia con insulina o sulfonilureas. Evitar en embarazo y lactancia.","El INVIMA ha alertado sobre productos sin registro. Verificar lote y canal.","La hidratación y la titulación lenta reducen los síntomas digestivos. Si hay vómito persistente, dolor abdominal intenso o deshidratación, se suspende y se evalúa. La hipoglucemia es más probable cuando se combina con insulina o sulfonilureas, por lo que se ajustan esas dosis."]},{"titulo":"Educación","parrafos":["Explicar la titulación, los efectos digestivos y la hidratación. Revisar el costo y la adherencia. La pérdida de peso debe ser gradual y acompañada de alimentación y actividad.","No usar productos comprados por internet."]}],"errores":[{"error":"Iniciar con dosis alta.","correccion":"Empezar con 2,5 mg."},{"error":"No verificar registro.","correccion":"Verificar siempre."},{"error":"No ajustar insulina.","correccion":"Riesgo de hipoglucemia."}],"comprueba":[{"pregunta":"¿Dosis inicial?","respuesta":"2,5 mg semanal."},{"pregunta":"¿Cada cuánto se titula?","respuesta":"Cada cuatro semanas."},{"pregunta":"¿Qué verificar?","respuesta":"Registro sanitario, lote y canal."}],"resumen":["Tirzepatida: **GIP/GLP-1**.","Inicio 2,5 mg y titulación.","Vigilar gastrointestinal y tiroides.","Verificar registro."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Mounjaro 10 mg/dosis KwikPen solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/1221685055/FT_1221685055.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con escalera de dosis 2,5 a 15 mg y sello de verificación de registro.","alt":"Ficha rápida de tirzepatida"}],"keywords":["tirzepatida ficha","tirzepatida dosis","tirzepatida titulación","tirzepatida seguridad","tirzepatida registro"],"mapa":{"centro":"Tirzepatida","ramas":[{"titulo":"Dosis","icono":"Syringe","nodos":["2,5 mg","Cada 4 semanas","Máx. 15 mg"]},{"titulo":"Efectos","icono":"Scale","nodos":["HbA1c","Peso","Saciedad"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Náuseas","Pancreatitis","Tiroides"]},{"titulo":"Registro","icono":"ShieldCheck","nodos":["INVIMA","Lote","Canal"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Registro","detalle":"Verificar INVIMA y lote.","icono":"ShieldCheck","evidencia":"Registro."},{"titulo":"Dosis","detalle":"Inicio 2,5 mg y titulación.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Seguridad","detalle":"Tiroides, pancreatitis y embarazo.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"Técnica y efectos.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"Peso, HbA1c y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Dosis de 15 mg de inicio","contexto":"Paciente quiere empezar tirzepatida con 15 mg para bajar rápido.","pregunta":"¿Qué responder?","opciones":[{"texto":"Aceptar porque es más eficaz.","correcta":false,"retro":"La dosis alta de inicio aumenta los efectos adversos."},{"texto":"Explicar la titulación desde 2,5 mg y el seguimiento.","correcta":true,"retro":"La titulación gradual es segura y eficaz."},{"texto":"Recomendar 7,5 mg.","correcta":false,"retro":"No se inicia con dosis intermedias altas."}]}}$j$::jsonb;
