  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de dapagliflozina","texto":"Dapagliflozina es un iSGLT2 con beneficio en insuficiencia cardíaca y enfermedad renal. Esta ficha resume dosis, seguridad y educación. La dosis habitual es 10 mg al día y requiere revisar la TFG, el volumen y los diuréticos. Educar sobre infecciones genitales, cetoacidosis y reglas de días de enfermedad. La revisión de diuréticos y presión evita hipotensión; la educación sobre días de enfermedad previene cetoacidosis. La ficha incluye la técnica de dispensación, los signos de alarma y el seguimiento de la función renal. Revisar siempre el registro sanitario y la indicación."},"objetivos":["Recordar dosis e indicaciones.","Aplicar ajuste por TFG.","Reconocer efectos adversos y reglas de días de enfermedad.","Educar sobre cetoacidosis e infecciones."],"conceptos":[{"icono":"Droplets","termino":"iSGLT2","definicion":"Inhibidor renal que aumenta la glucosuria y reduce eventos cardiorrenales."},{"icono":"Activity","termino":"Insuficiencia cardíaca","definicion":"Indicación con beneficio demostrado."},{"icono":"AlertTriangle","termino":"Cetoacidosis","definicion":"Riesgo raro pero grave."},{"icono":"ShieldCheck","termino":"Días de enfermedad","definicion":"Suspender en enfermedad aguda y cirugía."}],"secciones":[{"titulo":"Dosis e indicaciones","parrafos":["La dosis habitual es 10 mg una vez al día. Se usa en diabetes tipo 2, insuficiencia cardíaca y enfermedad renal crónica, según la indicación y la TFG. El beneficio cardiorrenal no depende solo de la glucosa.","Revisar la TFG antes de iniciar y durante el seguimiento. La caída inicial leve puede ser esperada."]},{"titulo":"Seguridad","parrafos":["Vigilar infecciones genitales, depleción de volumen y cetoacidosis euglucémica. Suspender en enfermedad aguda, cirugía o ayuno prolongado. Revisar diuréticos y presión.","La higiene y la hidratación reducen complicaciones. No se debe suspender por una infección leve sin consultar."]},{"titulo":"Educación","parrafos":["Explicar la micción, la hidratación y los signos de infección. Enseñar las reglas de días de enfermedad. Revisar la función renal y la presión.","La dapagliflozina no causa hipoglucemia por sí sola, pero el riesgo aumenta con insulina o sulfonilureas."]}],"errores":[{"error":"No revisar TFG.","correccion":"Revisar antes y durante."},{"error":"No educar sobre cetoacidosis.","correccion":"Explicar síntomas y suspensión."},{"error":"Ignorar infecciones genitales.","correccion":"Educar y tratar."}],"comprueba":[{"pregunta":"¿Dosis habitual?","respuesta":"10 mg al día."},{"pregunta":"¿Indicaciones?","respuesta":"DM2, insuficiencia cardíaca y ERC."},{"pregunta":"¿Cuándo suspender?","respuesta":"En cirugía, enfermedad aguda o ayuno prolongado."}],"resumen":["Dapagliflozina: **10 mg/día**.","Beneficio cardiorrenal.","Vigilar volumen, infecciones y cetoacidosis.","Reglas de días de enfermedad."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Dapagliflozina Aurovitas 10 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/89963/FT_89963.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con comprimido, corazón, riñón y semáforo de días de enfermedad.","alt":"Ficha rápida de dapagliflozina"}],"keywords":["dapagliflozina ficha","dapagliflozina dosis","dapagliflozina insuficiencia cardiaca","dapagliflozina erc","dapagliflozina seguridad"],"mapa":{"centro":"Dapagliflozina","ramas":[{"titulo":"Dosis","icono":"Pill","nodos":["10 mg/día","Una vez","Con o sin comida"]},{"titulo":"Indicaciones","icono":"Target","nodos":["DM2","IC","ERC"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Infecciones","Volumen","Cetoacidosis"]},{"titulo":"Educación","icono":"Users","nodos":["Hidratación","Higiene","Suspensión"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"DM2, IC o ERC.","icono":"Target","evidencia":"Fórmula."},{"titulo":"TFG","detalle":"Revisar y ajustar.","icono":"Droplets","evidencia":"Resultado."},{"titulo":"Seguridad","detalle":"Volumen, infecciones y cetoacidosis.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educación","detalle":"Hidratación y días de enfermedad.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguimiento","detalle":"TFG, presión y síntomas.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Cirugía programada","contexto":"Paciente con dapagliflozina y cirugía programada.","pregunta":"¿Qué hacer?","opciones":[{"texto":"Continuar hasta el día de la cirugía.","correcta":false,"retro":"Se suspende según protocolo para evitar cetoacidosis."},{"texto":"Suspender antes de la cirugía y reiniciar cuando esté estable.","correcta":true,"retro":"Las reglas de días de enfermedad incluyen cirugía."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Nunca duplicar."}]}}$j$::jsonb;
