  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"La ficha de liraglutida","texto":"Liraglutida es un GLP-1 diario con titulación semanal. Esta ficha resume dosis, seguridad y educación. Se inicia con 0,6 mg al día y se aumenta según tolerancia. Revisar antecedentes de tiroides, pancreatitis y embarazo, y educar sobre náuseas, conservación y técnica de inyección. La titulación semanal reduce los síntomas digestivos; si son intensos, se mantiene o reduce la dosis. La pluma se conserva refrigerada antes del primer uso y se revisa la técnica en cada control. La pérdida de peso debe acompañarse de alimentación y actividad, y el seguimiento incluye tolerancia, adherencia y costo. La ficha también recuerda verificar el registro sanitario y no usar productos comprados por internet. La educación y el seguimiento son parte del tratamiento. Revisar la técnica de inyección y la conservación en cada control."},"objetivos":["Recordar la titulación y la dosis.","Reconocer efectos adversos y contraindicaciones.","Educar sobre técnica y conservación.","Identificar signos de alarma."],"conceptos":[{"icono":"Activity","termino":"GLP-1","definicion":"Agonista que reduce glucosa y peso."},{"icono":"Syringe","termino":"Titulación","definicion":"0,6 mg y aumentos semanales."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Gastrointestinal, pancreatitis, tiroides."},{"icono":"Users","termino":"Educación","definicion":"Técnica, conservación y adherencia."}],"secciones":[{"titulo":"Dosis","parrafos":["Iniciar 0,6 mg al día durante una semana y aumentar a 1,2 mg; luego 1,8, 2,4 o 3 mg según objetivo y tolerancia. La titulación semanal reduce los síntomas digestivos.","Revisar la técnica de inyección y la conservación. No duplicar dosis olvidadas."]},{"titulo":"Seguridad","parrafos":["Náuseas, vómito, diarrea y estreñimiento son frecuentes. Vigilar pancreatitis, colelitiasis, tiroides e hipoglucemia con insulina o sulfonilureas. Evitar en embarazo, lactancia y antecedente de carcinoma medular de tiroides o MEN2.","La deshidratación por vómito requiere evaluación."]},{"titulo":"Educación","parrafos":["Explicar la titulación, los efectos digestivos y la hidratación. Revisar el costo y la adherencia. La pérdida de peso debe ser gradual y acompañada de alimentación y actividad.","No usar productos comprados por internet."]}],"errores":[{"error":"Iniciar con dosis alta.","correccion":"Empezar con 0,6 mg."},{"error":"No preguntar por tiroides.","correccion":"Revisar antecedentes."},{"error":"No revisar técnica.","correccion":"La técnica afecta la eficacia."}],"comprueba":[{"pregunta":"¿Dosis inicial?","respuesta":"0,6 mg al día."},{"pregunta":"¿Cómo se titula?","respuesta":"Aumentos semanales según tolerancia."},{"pregunta":"¿Qué vigilar?","respuesta":"Gastrointestinal, pancreatitis y tiroides."}],"resumen":["Liraglutida: **GLP-1 diario**.","Inicio 0,6 mg y titulación.","Vigilar gastrointestinal y tiroides.","Educación y adherencia."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Saxenda 6 mg/ml solución inyectable en pluma precargada.","url":"https://cima.aemps.es/cima/dochtml/ft/115992002/FT_115992002.html"}],"imagenes":[{"ubicacion":"Ficha","descripcion":"Tarjeta con pluma diaria, escalera de titulación y lista de seguridad.","alt":"Ficha rápida de liraglutida"}],"keywords":["liraglutida ficha","liraglutida dosis","liraglutida titulación","liraglutida seguridad","liraglutida obesidad"],"mapa":{"centro":"Liraglutida","ramas":[{"titulo":"Dosis","icono":"Syringe","nodos":["0,6 mg","Semanal","Hasta 3 mg"]},{"titulo":"Efectos","icono":"Scale","nodos":["HbA1c","Peso","Saciedad"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Náuseas","Pancreatitis","Tiroides"]},{"titulo":"Educación","icono":"Users","nodos":["Técnica","Conservación","Adherencia"]}]},"proceso":{"titulo":"Checklist de dispensación","intro":"","pasos":[{"titulo":"Indicación","detalle":"DM2 u obesidad.","icono":"Target","evidencia":"Fórmula."},{"titulo":"Dosis","d